/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Exports
 *   Types: ExpectedTracklistSource, ExpectedTracklistRow, AlbumExpectedTracklist, ExpectedTracklistRejection,
 *          ExpectedTracklistParse, ExpectedTrackPosition, ExpectedTrackMember, ExpectedTrackRowView,
 *          ExpectedTracklistPair
 *   Functions: parseExpectedTracklistRows, hasStoredExpectedTracklist, storedExpectedTracklist,
 *              expectedTracklistForStorage, expectedTrackPosition, expectedTrackRows, expectedTracklistPlaced
 *   Constants: EXPECTED_TRACKLIST_LIMITS, withoutExpectedTracklistProjection, withoutExpectedTracklistStage
 * Internal
 *   Functions: isPlainObject, wholeNumber, isValidDate, positionKey, refuse
 *   Constants: rowKeys, sources, invisible
 * @end-catalog */

/**
 * An Album's expected tracklist: the audio tracklist of the release an applied existing-Album review used. This module validates
 * its rows and matches them to members by Disc and Track Number when they are read, so the Album stores no member link. Pure: no
 * I/O and no environment.
 */
import { embeddedDiscNumber, embeddedTrackNumber } from '../audio/audioMetadataService';

export type ExpectedTracklistSource = 'musicbrainz' | 'itunes';
export type ExpectedTracklistRow = { discNumber: number; trackNumber: number; title: string; durationMs: number | null };
/** Stored at Album.expectedTracklist. It keeps no release, recording or iTunes ID and no MediaTrack reference. */
export type AlbumExpectedTracklist = { source: ExpectedTracklistSource; appliedAt: Date; rows: ExpectedTracklistRow[] };
/** Disc and Track Number bounds match the Album sort key; `bytes` bounds the UTF-8 JSON of the normalized, sorted rows. */
export const EXPECTED_TRACKLIST_LIMITS = Object.freeze({ rows: 100, bytes: 32_768, title: 300, disc: 999, track: 9_999 });
export type ExpectedTracklistRejection = 'format' | 'tooManyRows' | 'characters' | 'length' | 'duplicatePosition' | 'size';
export type ExpectedTracklistParse = { ok: true; rows: ExpectedTracklistRow[] } | { ok: false; reason: ExpectedTracklistRejection };

const rowKeys = ['discNumber', 'trackNumber', 'title', 'durationMs'];
const sources: readonly string[] = ['musicbrainz', 'itunes'];
/** The lookup automatic-text rule: controls, invisible formatting characters and lone surrogates. */
const invisible = /[\p{Cc}\p{Cf}\p{Cs}]/u;
const isPlainObject = (value: unknown): value is Record<string, unknown> => {
    if (!value || typeof value !== 'object' || Array.isArray(value)) return false;
    const prototype = Object.getPrototypeOf(value);
    return prototype === Object.prototype || prototype === null;
};
const wholeNumber = (value: unknown, maximum: number): value is number =>
    typeof value === 'number' && Number.isSafeInteger(value) && value >= 1 && value <= maximum;
const isValidDate = (value: unknown): value is Date => value instanceof Date && !Number.isNaN(value.getTime());
const positionKey = (discNumber: number, trackNumber: number) => `${discNumber}:${trackNumber}`;
const refuse = (reason: ExpectedTracklistRejection): { ok: false; reason: ExpectedTracklistRejection } => ({ ok: false, reason });

/**
 * Validates the rows array, which is also a review's draft value (two container levels). The first failure wins, checked in
 * input order; the result is sorted by Disc then Track Number with a fixed key order, so parsing it again returns it unchanged
 * and writers store only parser output.
 */
export function parseExpectedTracklistRows(value: unknown): ExpectedTracklistParse {
    if (!Array.isArray(value) || value.length === 0) return refuse('format');
    if (value.length > EXPECTED_TRACKLIST_LIMITS.rows) return refuse('tooManyRows');
    const rows: ExpectedTracklistRow[] = [];
    const positions = new Set<string>();
    for (const raw of value) {
        if (!isPlainObject(raw)) return refuse('format');
        const keys = Reflect.ownKeys(raw);
        if (keys.length !== rowKeys.length || !keys.every(key => typeof key === 'string' && rowKeys.includes(key))) return refuse('format');
        const { discNumber, trackNumber, title, durationMs } = raw;
        if (!wholeNumber(discNumber, EXPECTED_TRACKLIST_LIMITS.disc) || !wholeNumber(trackNumber, EXPECTED_TRACKLIST_LIMITS.track)) return refuse('format');
        // Any positive whole number of milliseconds: the size bound already limits the value.
        if (durationMs !== null && !(typeof durationMs === 'number' && Number.isSafeInteger(durationMs) && durationMs >= 1)) return refuse('format');
        if (typeof title !== 'string') return refuse('format');
        const normalized = title.normalize('NFC').trim();
        if (!normalized) return refuse('format');
        if (invisible.test(normalized)) return refuse('characters');
        // UTF-16 units, as other 300-character catalog titles are counted.
        if (normalized.length > EXPECTED_TRACKLIST_LIMITS.title) return refuse('length');
        const key = positionKey(discNumber, trackNumber);
        if (positions.has(key)) return refuse('duplicatePosition');
        positions.add(key);
        rows.push({ discNumber, trackNumber, title: normalized, durationMs });
    }
    rows.sort((left, right) => left.discNumber - right.discNumber || left.trackNumber - right.trackNumber);
    if (Buffer.byteLength(JSON.stringify(rows), 'utf8') > EXPECTED_TRACKLIST_LIMITS.bytes) return refuse('size');
    return { ok: true, rows };
}

/** Whether a value is stored at all; a malformed one still counts, so it enters the Album revision. */
export const hasStoredExpectedTracklist = (doc: { expectedTracklist?: unknown }): boolean =>
    doc.expectedTracklist !== undefined && doc.expectedTracklist !== null;

/**
 * Lenient reader of a stored tracklist: a malformed value reads as none (it still changes the revision), and unknown top-level
 * keys are ignored so a later format can add one.
 */
export function storedExpectedTracklist(doc: { expectedTracklist?: unknown } | null | undefined): AlbumExpectedTracklist | null {
    if (!doc || !hasStoredExpectedTracklist(doc)) return null;
    const stored = doc.expectedTracklist;
    if (!isPlainObject(stored) || typeof stored.source !== 'string' || !sources.includes(stored.source) || !isValidDate(stored.appliedAt)) return null;
    const parsed = parseExpectedTracklistRows(stored.rows);
    return parsed.ok ? { source: stored.source as ExpectedTracklistSource, appliedAt: new Date(stored.appliedAt.getTime()), rows: parsed.rows } : null;
}

/**
 * Builds the value a writer stores, in a fixed key order so stored bytes and revisions are deterministic. Writers map an unknown
 * duration, including the iTunes 0, to null before calling it.
 */
export function expectedTracklistForStorage(source: unknown, appliedAt: unknown, rows: unknown):
    { ok: true; tracklist: AlbumExpectedTracklist } | { ok: false; reason: ExpectedTracklistRejection } {
    if (typeof source !== 'string' || !sources.includes(source) || !isValidDate(appliedAt)) return refuse('format');
    const parsed = parseExpectedTracklistRows(rows);
    if (!parsed.ok) return parsed;
    return { ok: true, tracklist: { source: source as ExpectedTracklistSource, appliedAt: new Date(appliedAt.getTime()), rows: parsed.rows } };
}

export type ExpectedTrackPosition = { discNumber: number; trackNumber: number };
/** A member's position as the Album sort key sees it: no valid Track Number means none, and a missing Disc Number is disc 1. */
export const expectedTrackPosition = (discNumber: unknown, trackNumber: unknown): ExpectedTrackPosition | null => {
    const track = embeddedTrackNumber(trackNumber);
    return track === undefined ? null : { discNumber: embeddedDiscNumber(discNumber) ?? 1, trackNumber: track };
};

export type ExpectedTrackMember = { id: string; discNumber: unknown; trackNumber: unknown };
export type ExpectedTrackRowView = ExpectedTracklistRow & { memberIds: string[] };
/**
 * Derives the expected rows: each member, whatever its lifecycle state or visibility, is listed on the row at its position (all
 * members at one position fill that row). A row without members is a missing-file row, and a member at no row's position is
 * outside the expected tracklist. Rows keep their order and are assumed to be parser output; members are assumed distinct.
 */
export function expectedTrackRows(rows: readonly ExpectedTracklistRow[], members: readonly ExpectedTrackMember[]):
    { rows: ExpectedTrackRowView[]; outsideMemberIds: string[] } {
    const byPosition = new Map<string, ExpectedTrackRowView>();
    const views = rows.map(row => {
        const view: ExpectedTrackRowView = { discNumber: row.discNumber, trackNumber: row.trackNumber, title: row.title, durationMs: row.durationMs, memberIds: [] };
        const key = positionKey(row.discNumber, row.trackNumber);
        if (!byPosition.has(key)) byPosition.set(key, view);
        return view;
    });
    const outsideMemberIds: string[] = [];
    for (const member of members) {
        const position = expectedTrackPosition(member.discNumber, member.trackNumber);
        const view = position ? byPosition.get(positionKey(position.discNumber, position.trackNumber)) : undefined;
        if (view) view.memberIds.push(member.id); else outsideMemberIds.push(member.id);
    }
    return { rows: views, outsideMemberIds };
}

export type ExpectedTracklistPair = { slotId: string; discNumber: number; trackNumber: number };
/**
 * Whether every paired member sits at an existing row once the selected changes apply: the pair's position must be a row, and the
 * member's resulting numbers (`numbers`, by slot) must give that same position. Empty pairs are placed; off slots are listed once,
 * in pair order.
 */
export function expectedTracklistPlaced(rows: readonly ExpectedTracklistRow[], pairs: readonly ExpectedTracklistPair[],
    numbers: ReadonlyMap<string, { discNumber: unknown; trackNumber: unknown }>): { placed: true } | { placed: false; offSlotIds: string[] } {
    const positions = new Set(rows.map(row => positionKey(row.discNumber, row.trackNumber)));
    const offSlotIds: string[] = [];
    for (const pair of pairs) {
        const member = numbers.get(pair.slotId);
        const position = member ? expectedTrackPosition(member.discNumber, member.trackNumber) : null;
        const placed = positions.has(positionKey(pair.discNumber, pair.trackNumber)) && position !== null
            && position.discNumber === pair.discNumber && position.trackNumber === pair.trackNumber;
        if (!placed && !offSlotIds.includes(pair.slotId)) offSlotIds.push(pair.slotId);
    }
    return offSlotIds.length ? { placed: false, offSlotIds } : { placed: true };
}

/** Exclusion used by listener reads that load whole Album documents: the tracklist is administrator information. */
export const withoutExpectedTracklistProjection = Object.freeze({ expectedTracklist: 0 } as const);
/** The same exclusion as an aggregation stage. */
export const withoutExpectedTracklistStage = Object.freeze({ $unset: 'expectedTracklist' } as const);
